174	    @Override
175	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        this.clinicService.deleteOwner(owner);
181	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
187	        Owner owner = this.clinicService.findOwnerById(ownerId);
188	        if (owner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        HttpHeaders headers = new HttpHeaders();
192	        Pet pet = petMapper.toPet(petFieldsDto);
193	        owner.setId(ownerId);
194	        pet.setOwner(owner);
195	        pet.getType().setName(null);
196	        this.clinicService.savePet(pet);
197	        PetDto petDto = petMapper.toPetDto(pet);
198	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
199	            .buildAndExpand(pet.getId()).toUri());
200	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
206	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
207	        if (currentOwner != null) {
208	            Pet currentPet = this.clinicService.findPetById(petId);
209	            if (currentPet != null) {
210	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
211	                currentPet.setName(petFieldsDto.getName());
212	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
213	                this.clinicService.savePet(currentPet);
214	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
215	            }
216	        }
217	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
223	        HttpHeaders headers = new HttpHeaders();
224	        Visit visit = visitMapper.toVisit(visitFieldsDto);
225	        Pet pet = new Pet();
226	        pet.setId(petId);
227	        visit.setPet(pet);
228	        this.clinicService.saveVisit(visit);
229	        VisitDto visitDto = visitMapper.toVisitDto(visit);
230	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
231	            .buildAndExpand(visit.getId()).toUri());
232	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
233	    }
234	
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
239	        Owner owner = this.clinicService.findOwnerById(ownerId);
240	        if (owner != null) {
241	            Pet pet = owner.getPet(petId);
242	            if (pet != null) {
243	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
244	            }
245	        }
246	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	    }
248	
249	    /**
250	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
251	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
252	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
253	     *
254	     * @param ownerFieldsDto the submitted owner fields
255	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
256	     *                                     name of every offending field
257	     */
258	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
259	        List<String> missingFields = new ArrayList<>();
260	        if (isBlank(ownerFieldsDto.getFirstName())) {
261	            missingFields.add("firstName");
262	        }
263	        if (isBlank(ownerFieldsDto.getLastName())) {
264	            missingFields.add("lastName");
265	        }
266	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
267	            missingFields.add("address");
268	        }
269	        if (isBlank(ownerFieldsDto.getCity())) {
270	            missingFields.add("city");
271	        }
272	        if (isBlank(ownerFieldsDto.getTelephone())) {
273	            missingFields.add("telephone");
274	        }
275	        if (!missingFields.isEmpty()) {
276	            throw new InvalidOwnerFieldsException(missingFields);
277	        }
278	    }
279	
280	    private boolean isBlank(String value) {
281	        return value == null || value.isBlank();
282	    }
283	
284	    /**
285	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
286	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
287	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
288	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
289	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
290	     *
291	     * @param telephone the raw telephone value submitted by the client
292	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
293	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
294	     *                                     400 response
295	     */
296	    private String normalizeTelephone(String telephone) {
297	        String e164 = toE164(telephone);
298	        if (e164 == null) {
299	            throw new InvalidOwnerFieldsException(List.of("telephone"));
300	        }
301	        return e164;
302	    }
303	
304	    /**
305	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
306	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
307	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
308	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
309	     *
310	     * @param telephone the raw telephone value, possibly {@code null}
311	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
312	     */
313	    private String toE164(String telephone) {
314	        if (telephone == null) {
315	            return null;
316	        }
317	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
318	        boolean hasPlus = cleaned.startsWith("+");
319	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
320	        String nationalSignificant = hasPlus
321	            ? digits
322	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
323	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
324	            return null;
325	        }
326	        return "+" + nationalSignificant;
327	    }
328	
329	    /**
330	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
331	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
332	     * returned value is that address lower-cased.
333	     *
334	     * @param email the raw email value submitted by the client, or {@code null} if omitted
335	     * @return the lower-cased email, or {@code null} if none was supplied
336	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
337	     *                                     yielding a 400 response
338	     */
339	    private String normalizeEmail(String email) {
340	        if (email == null) {
341	            return null;
342	        }
343	        if (!EMAIL_PATTERN.matcher(email).matches()) {
344	            throw new InvalidOwnerFieldsException(List.of("email"));
345	        }
346	        return email.toLowerCase(Locale.ROOT);
347	    }
348	
349	    /**
350	     * Counts the existing owners that, before this create, already share the given first name and
351	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
352	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
353	     * been saved yet, so it is never included in the count.
354	     *
355	     * @param firstName the first name of the owner being created
356	     * @param lastName  the last name of the owner being created
357	     * @return the number of existing owners sharing both names
358	     */
359	    private int countNamesakes(String firstName, String lastName) {
360	        String normalizedFirstName = normalizeForComparison(firstName);
361	        String normalizedLastName = normalizeForComparison(lastName);
362	        return (int) this.clinicService.findAllOwners().stream()
363	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
364	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
365	            .count();
366	    }
367	
368	    /**
369	     * Builds the owner's {@code customerCode}, formatted {@code '<LAST3>-<NNNN>'}. {@code LAST3} is
370	     * the upper-cased first three letters of the last name, and {@code NNNN} is a global 4-digit
371	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
372	     *
373	     * @param lastName the owner's last name
374	     * @return the formatted customer code
375	     */
376	    private String generateCustomerCode(String lastName) {
377	        String letters = lastName.replaceAll("[^\\p{L}]", "");
378	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
379	        int sequence = this.clinicService.findAllOwners().size() + 1;
380	        return String.format("%s-%04d", last3, sequence);
381	    }
382	
383	    /**
384	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
385	     * telephones are converted to E.164 here as well so the comparison is independent of the format
386	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
387	     * ignored rather than matched.
388	     *
389	     * @param telephone the E.164 telephone of the owner being created
390	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
391	     *                                          yielding a 409 Conflict response
392	     */
393	    private void rejectDuplicateTelephone(String telephone) {
394	        boolean inUse = this.clinicService.findAllOwners().stream()
395	            .map(Owner::getTelephone)
396	            .map(this::toE164)
397	            .anyMatch(telephone::equals);
398	        if (inUse) {
399	            throw new DuplicateOwnerTelephoneException(telephone);
400	        }
401	    }
402	
403	    /**
404	     * Rejects creation of an owner whose last name and address both match an existing owner's,
405	     * which marks them as belonging to the same household. Both the last name and the address are
406	     * compared case-insensitively with surrounding and internal whitespace collapsed, so values
407	     * that differ only in letter case or spacing are still treated as a match.
408	     *
409	     * @param lastName the last name of the owner being created
410	     * @param address  the address of the owner being created
411	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
412	     *                                          address, yielding a 409 Conflict response
413	     */
414	    private void rejectDuplicateHousehold(String lastName, String address) {
415	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
416	            throw new DuplicateOwnerHouseholdException(lastName, address);
417	        }
418	    }
419	
420	    /**
421	     * Finds every existing owner belonging to the household identified by the given last name and
422	     * address — that is, the owners the duplicate-household rule rejects and the {@code sharesHousehold}
423	     * opt-in joins. Both the last name and the address are compared case-insensitively with surrounding
424	     * and internal whitespace collapsed, so values that differ only in letter case or spacing still
425	     * match. This single definition of household membership is shared by {@link #rejectDuplicateHousehold}
426	     * and {@link #assignHousehold}.
427	     *
428	     * @param lastName the last name of the owner being created
429	     * @param address  the address of the owner being created
430	     * @return the existing owners in that household, or an empty list if there are none
431	     */
432	    private List<Owner> findHouseholdMembers(String lastName, String address) {
433	        String normalizedLastName = normalizeForComparison(lastName);
434	        String normalizedAddress = normalizeAddress(address);
435	        return this.clinicService.findAllOwners().stream()
436	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
437	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
438	            .toList();
439	    }
440	
441	    /**
442	     * Enrolls a newly created owner into the household of any existing owner that shares its last
443	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
444	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
445	     * whitespace. When at least one such owner already exists, every member of the household — the
446	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
447	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
448	     * and address is created and back-filled onto the existing members. When no owner yet lives at
449	     * that address under the same last name no identifier is assigned and the owner is created alone.
450	     *
451	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
452	     * @param lastName the last name of the owner being created
453	     * @param address  the address of the owner being created
454	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
455	     */
456	    private String assignHousehold(Owner newOwner, String lastName, String address) {
457	        List<Owner> members = findHouseholdMembers(lastName, address);
458	        if (members.isEmpty()) {
459	            return null;
460	        }
461	        String householdId = members.stream()
462	            .map(Owner::getHouseholdId)
463	            .filter(existing -> existing != null && !existing.isBlank())
464	            .findFirst()
465	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
466	        for (Owner member : members) {
467	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
468	                member.setHouseholdId(householdId);
469	                this.clinicService.saveOwner(member);
470	            }
471	        }
472	        newOwner.setHouseholdId(householdId);
473	        return householdId;
474	    }
475	
476	    /**
477	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
478	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
479	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
480	     * same identifier, so members of one household share a single value.
481	     *
482	     * @param normalizedLastName the household's last name, already normalized for comparison
483	     * @param normalizedAddress  the household's address, already normalized for comparison
484	     * @return the derived household identifier
485	     */
486	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
487	        try {
488	            byte[] digest = MessageDigest.getInstance("SHA-256")
489	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
490	            StringBuilder hex = new StringBuilder(digest.length * 2);
491	            for (byte b : digest) {
492	                hex.append(String.format("%02x", b));
493	            }
494	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
495	        } catch (NoSuchAlgorithmException e) {
496	            throw new IllegalStateException("SHA-256 algorithm not available", e);
497	        }
498	    }
499	
500	    /**
501	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
502	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
503	     * the result is lower-cased.
504	     *
505	     * @param value the value to normalize, possibly {@code null}
506	     * @return the normalized value, or an empty string if {@code value} is {@code null}
507	     */
508	    private String normalizeForComparison(String value) {
509	        if (value == null) {
510	            return "";
511	        }
512	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
513	    }
514	
515	    /**
516	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
517	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
518	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
519	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
520	     * This normalized value is what gets stored and returned, and it is the form every address
521	     * comparison (household duplicate detection and the shared household id) uses.
522	     *
523	     * @param address the raw address value submitted by the client, possibly {@code null}
524	     * @return the normalized address, or an empty string if {@code address} is {@code null}
525	     */
526	    private String normalizeAddress(String address) {
527	        if (address == null) {
528	            return "";
529	        }
530	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
531	        if (collapsed.isEmpty()) {
532	            return collapsed;
533	        }
534	        String[] tokens = collapsed.split(" ");
535	        StringBuilder normalized = new StringBuilder(collapsed.length());
536	        for (int i = 0; i < tokens.length; i++) {
537	            if (i > 0) {
538	                normalized.append(' ');
539	            }
540	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
541	        }
542	        return normalized.toString();
543	    }
544	}
